"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["6275"],{62860(e){e.exports=JSON.parse('{"id":"F444","slug":"unhedged-foreign-return","name":"Emerging Market Return: Local, Unhedged and Hedged","subject":"International Finance","section":"Global Finance","topic":"Emerging markets investing","level":"Intermediate","aliases":["emerging markets investing","currency return","hedging cost","local currency return"],"formula":{"latex":"R_{USD}=(1+R_{local})(1+\\\\Delta s)-1,\\\\quad R_{hedged}=(1+R_{local})\\\\frac{1+r_{d}}{1+r_{f}}-1","also":[],"text":"Dollar return unhedged = (1 + local return) x (1 + change in the local currency against the dollar) - 1; Dollar return hedged with a forward = (1 + local return) x (1 + dollar interest rate) / (1 + local interest rate) - 1. Hedging cost is roughly the local rate minus the dollar rate"},"symbols":[{"symbol":"R_local","meaning":"Return on the asset in local currency","unit":"percent"},{"symbol":"Delta s","meaning":"Change in the value of the local currency against the dollar","unit":"percent"},{"symbol":"r_d, r_f","meaning":"Dollar and local short-term interest rates","unit":"per year"}],"when_to_use":"Use it to split an emerging market return into the asset and the currency. High local returns are often offset by currency depreciation, especially where inflation is high. Hedging removes the currency move but costs the interest differential, which is large when local rates are high, so the hedged return is lower when the currency would otherwise have held. Choose by comparing the hedging cost with the depreciation you fear.","worked_example":{"problem":"A local bond market returns 12% in local currency. The local currency falls 8% against the dollar. Dollar rates are 4% and local rates 9%.","inputs":{"rl":12,"ds":-8,"rd":4,"rf":9},"steps":[{"label":"Unhedged USD return","working":"(1+0.12) x (1+-0.08)-1","value":"3.04%"},{"label":"Hedged USD return","working":"(1+0.12) x (1+0.04) / (1+0.09)-1","value":"6.86%"},{"label":"Approximate hedging cost = local rate - dollar rate","working":"0.09-0.04","value":"5.00%"},{"label":"Hedged better? (1 = yes, 0 = no)","working":"1 if 0.0686239>0.0304 else 0","value":"1"},{"label":"Hedged minus unhedged","working":"0.0686239-0.0304","value":"3.82%"}],"answer":"Unhedged, the dollar return is 3.04%, well below the local 12% because of the currency fall. Hedged, the return is 6.86%, since the hedge costs about 5.00% a year. The hedge-better flag is 1 (1 = hedged was better, 0 = unhedged was better)."},"calculator":{"available":true,"inputs":[{"id":"rl","label":"Local currency return","unit":"%","type":"number","default":12,"hint":""},{"id":"ds","label":"Change in the local currency vs USD","unit":"%","type":"number","default":-8,"hint":""},{"id":"rd","label":"Dollar interest rate","unit":"%","type":"number","default":4,"hint":""},{"id":"rf","label":"Local interest rate","unit":"%","type":"number","default":9,"hint":""}],"checks":[{"expr":"rd>-1 and rf>-1","message":"Enter valid interest rates."}],"steps":[{"id":"unh","label":"Unhedged USD return","expr":"(1+rl)*(1+ds)-1","format":"pct2"},{"id":"hed","label":"Hedged USD return","expr":"(1+rl)*(1+rd)/(1+rf)-1","format":"pct2"},{"id":"cost","label":"Approximate hedging cost = local rate - dollar rate","expr":"rf-rd","format":"pct2"},{"id":"better_","label":"Hedged better? (1 = yes, 0 = no)","expr":"1 if hed>unh else 0","format":"num0"},{"id":"diff","label":"Hedged minus unhedged","expr":"hed-unh","format":"pct2"}],"results":["unh","hed","diff"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"unh":3.0400000000000205e-2,"hed":0.06862385321100906,"cost":0.05,"better_":1,"diff":0.03822385321100885}},"finder":{"finds":"What a local return is worth in dollars, hedged and unhedged","needs":"Local return, currency change, interest rates"},"related":[{"slug":"uncovered-interest-parity","name":"Uncovered Interest Parity and Unhedged Return"},{"slug":"carry-trade-return","name":"Carry Trade Return and Break-Even"},{"slug":"country-risk-premium","name":"Country Risk Premium"}],"related_ids":["F435","F438","F167"],"group":"Money, banks and the economy","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><msub><mi>R</mi><mrow><mi>U</mi><mi>S</mi><mi>D</mi></mrow></msub><mo>=</mo><mo stretchy=\\"false\\">(</mo><mn>1</mn><mo>+</mo><msub><mi>R</mi><mrow><mi>l</mi><mi>o</mi><mi>c</mi><mi>a</mi><mi>l</mi></mrow></msub><mo stretchy=\\"false\\">)</mo><mo stretchy=\\"false\\">(</mo><mn>1</mn><mo>+</mo><mi mathvariant=\\"normal\\">\u0394</mi><mi>s</mi><mo stretchy=\\"false\\">)</mo><mo>\u2212</mo><mn>1</mn><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><msub><mi>R</mi><mrow><mi>h</mi><mi>e</mi><mi>d</mi><mi>g</mi><mi>e</mi><mi>d</mi></mrow></msub><mo>=</mo><mo stretchy=\\"false\\">(</mo><mn>1</mn><mo>+</mo><msub><mi>R</mi><mrow><mi>l</mi><mi>o</mi><mi>c</mi><mi>a</mi><mi>l</mi></mrow></msub><mo stretchy=\\"false\\">)</mo><mfrac><mrow><mn>1</mn><mo>+</mo><msub><mi>r</mi><mi>d</mi></msub></mrow><mrow><mn>1</mn><mo>+</mo><msub><mi>r</mi><mi>f</mi></msub></mrow></mfrac><mo>\u2212</mo><mn>1</mn></mrow><annotation encoding=\\"application/x-tex\\">R_{USD}=(1+R_{local})(1+\\\\Delta s)-1,\\\\quad R_{hedged}=(1+R_{local})\\\\frac{1+r_{d}}{1+r_{f}}-1</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"emergency-fund-target","name":"Emergency Fund Target and Monthly Saving"},"next":{"slug":"employer-match-vesting","name":"Employer Match and Vesting"},"lesson":null,"total":522}')}}]);